  5016      /* Process the block contents accordingly to is type. */
  5017      switch(block->type) {
  5018          case MD_BLOCK_HR:
  5019              /* noop */
  5020              break;
  5021
  5022          case MD_BLOCK_CODE:
  5023              MD_CHECK(md_process_code_block_contents(ctx, (block->data != 0),
  5024                              (const MD_VERBATIMLINE*)(block + 1), block->n_lines));
  5025              break;
  5026
  5027          case MD_BLOCK_HTML:
  5028              MD_CHECK(md_process_verbatim_block_contents(ctx, MD_TEXT_HTML,
  5029                              (const MD_VERBATIMLINE*)(block + 1), block->n_lines));
  5030              break;
  5031
  5032          case MD_BLOCK_TABLE:
  5033              MD_CHECK(md_process_table_block_contents(ctx, block->data,
  5034                              (const MD_LINE*)(block + 1), block->n_lines));
  5035              break;
  5036
  5037          default:
  5038              MD_CHECK(md_process_normal_block_contents(ctx,
  5039                              (const MD_LINE*)(block + 1), block->n_lines));
  5040              break;
  5041      }
