  6190                  line->type = MD_LINE_SETEXTUNDERLINE;
  6191                  line->data = level;
  6192                  break;
  6193              }
  6194          }
  6195
  6196          /* Check for thematic break line. */
  6197          if(line->indent < ctx->code_indent_offset
  6198              &&  off < ctx->size  &&  off >= hr_killer
  6199              &&  ISANYOF(off, _T("-_*")))
  6200          {
  6201              if(md_is_hr_line(ctx, off, &off, &hr_killer)) {
  6202                  line->type = MD_LINE_HR;
  6203                  break;
  6204              }
  6205          }
  6206
  6207          /* Check for "brother" container. I.e. whether we are another list item
  6208           * in already started list. */
  6209          if(n_parents < ctx->n_containers  &&  n_brothers + n_children == 0) {
  6210              OFF tmp;
  6211
  6212              if(md_is_container_mark(ctx, line->indent, off, &tmp, &container)  &&
  6213                 md_is_container_compatible(&ctx->containers[n_parents], &container))
  6214              {
  6215                  pivot_line = &md_dummy_blank_line;
  6216
  6217                  off = tmp;
  6218
  6219                  total_indent += container.contents_indent - container.mark_indent;
  6220                  line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6221                  total_indent += line->indent;
  6222                  line->beg = off;
  6223
  6224                  /* Some of the following whitespace actually still belongs to the mark. */
  6225                  if(off >= ctx->size || ISNEWLINE(off)) {
  6226                      container.contents_indent++;
  6227                  } else if(line->indent <= ctx->code_indent_offset) {
  6228                      container.contents_indent += line->indent;
  6229                      line->indent = 0;
  6230                  } else {
  6231                      container.contents_indent += 1;
  6232                      line->indent--;
  6233                  }
  6234
  6235                  ctx->containers[n_parents].mark_indent = container.mark_indent;
  6236                  ctx->containers[n_parents].contents_indent = container.contents_indent;
