  6265                  total_indent += container.contents_indent - container.mark_indent;
  6266                  line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6267                  total_indent += line->indent;
  6268
  6269                  line->beg = off;
  6270                  line->data = container.ch;
  6271
  6272                  /* Some of the following whitespace actually still belongs to the mark. */
  6273                  if(off >= ctx->size || ISNEWLINE(off)) {
  6274                      container.contents_indent++;
  6275                  } else if(line->indent <= ctx->code_indent_offset) {
  6276                      container.contents_indent += line->indent;
  6277                      line->indent = 0;
  6278                  } else {
  6279                      container.contents_indent += 1;
  6280                      line->indent--;
  6281                  }
  6282
  6283                  if(n_brothers + n_children == 0)
  6284                      pivot_line = &md_dummy_blank_line;
  6285
  6286                  if(n_children == 0)
  6287                      MD_CHECK(md_leave_child_containers(ctx, n_parents + n_brothers));
