  6296          if(pivot_line->type == MD_LINE_TABLE  &&  n_parents == ctx->n_containers) {
  6297              line->type = MD_LINE_TABLE;
  6298              break;
  6299          }
  6300
  6301          /* Check for ATX header. */
  6302          if(line->indent < ctx->code_indent_offset  &&
  6303                  off < ctx->size  &&  CH(off) == _T('#'))
  6304          {
  6305              unsigned level;
  6306
  6307              if(md_is_atxheader_line(ctx, off, &line->beg, &off, &level)) {
  6308                  line->type = MD_LINE_ATXHEADER;
  6309                  line->data = level;
  6310                  break;
  6311              }
  6312          }
  6313
  6314          /* Check whether we are starting code fence. */
  6315          if(line->indent < ctx->code_indent_offset  &&
  6316                  off < ctx->size  &&  ISANYOF2(off, _T('`'), _T('~')))
  6317          {
  6318              if(md_is_opening_code_fence(ctx, off, &off)) {
  6319                  line->type = MD_LINE_FENCEDCODE;
  6320                  line->data = 1;
  6321                  line->enforce_new_block = TRUE;
  6322                  break;
  6323              }
  6324          }
  6325
  6326          /* Check for start of raw HTML block. */
  6327          if(off < ctx->size  &&  CH(off) == _T('<')
  6328              &&  !(ctx->parser.flags & MD_FLAG_NOHTMLBLOCKS))
  6329          {
  6330              ctx->html_block_type = md_is_html_block_start_condition(ctx, off);
  6331
