  6333              if(ctx->html_block_type == 7  &&  pivot_line->type == MD_LINE_TEXT)
  6334                  ctx->html_block_type = 0;
  6335
  6336              if(ctx->html_block_type > 0) {
  6337                  /* The line itself also may immediately close the block. */
  6338                  if(md_is_html_block_end_condition(ctx, off, &off) == ctx->html_block_type) {
  6339                      /* Make sure this is the last line of the block. */
  6340                      ctx->html_block_type = 0;
  6341                  }
  6342
  6343                  line->enforce_new_block = TRUE;
  6344                  line->type = MD_LINE_HTML;
  6345                  break;
  6346              }
  6347          }
  6348
  6349          /* Check for table underline. */
  6350          if((ctx->parser.flags & MD_FLAG_TABLES)  &&  pivot_line->type == MD_LINE_TEXT
  6351              &&  off < ctx->size  &&  ISANYOF3(off, _T('|'), _T('-'), _T(':'))
  6352              &&  n_parents == ctx->n_containers)
  6353          {
  6354              unsigned col_count;
  6355
  6356              if(ctx->current_block != NULL  &&  ctx->current_block->n_lines == 1  &&
  6357                  md_is_table_underline(ctx, off, &off, &col_count))
  6358              {
  6359                  line->data = col_count;
  6360                  line->type = MD_LINE_TABLEUNDERLINE;
  6361                  break;
  6362              }
  6363          }
  6364
  6365          /* By default, we are normal text line. */
  6366          line->type = MD_LINE_TEXT;
  6367          if(pivot_line->type == MD_LINE_TEXT  &&  n_brothers + n_children == 0) {
  6368              /* Lazy continuation. */
  6369              n_parents = ctx->n_containers;
  6370          }
  6371
  6372          /* Check for task mark. */
  6373          if((ctx->parser.flags & MD_FLAG_TASKLISTS)  &&  n_brothers + n_children > 0  &&
  6374             ISANYOF_(ctx->containers[ctx->n_containers-1].ch, _T("-+*.)")))
  6375          {
  6376              OFF tmp = off;
  6377
  6378              while(tmp < ctx->size  &&  tmp < off + 3  &&  ISBLANK(tmp))
  6379                  tmp++;
  6380              if(tmp + 2 < ctx->size  &&  CH(tmp) == _T('[')  &&
  6381                 ISANYOF(tmp+1, _T("xX "))  &&  CH(tmp+2) == _T(']')  &&
